# Validación de formularios

Con inputs controlados, tienes acceso al valor en todo momento, lo que permite validar de forma declarativa.

## Validación al hacer submit

```jsx
function FormularioLogin() {
  const [email, setEmail] = useState('');
  const [errores, setErrores] = useState({});

  function validar() {
    const nuevosErrores = {};

    if (!email) {
      nuevosErrores.email = 'El email es requerido';
    } else if (!email.includes('@')) {
      nuevosErrores.email = 'Email inválido';
    }

    return nuevosErrores;
  }

  function handleSubmit(e) {
    e.preventDefault();
    const erroresEncontrados = validar();

    if (Object.keys(erroresEncontrados).length > 0) {
      setErrores(erroresEncontrados);
      return; // No enviamos si hay errores
    }

    // Sin errores — proceder
    console.log('Enviando:', email);
  }

  return (
    <form onSubmit={handleSubmit}>
      <input
        value={email}
        onChange={e => setEmail(e.target.value)}
        placeholder="Email"
      />
      {errores.email && <span className="error">{errores.email}</span>}
      <button type="submit">Entrar</button>
    </form>
  );
}
```

## Validación en tiempo real

```jsx
// Valida mientras el usuario escribe
function manejarCambio(e) {
  const valor = e.target.value;
  setEmail(valor);

  if (!valor.includes('@')) {
    setError('Email inválido');
  } else {
    setError('');
  }
}
```

## Deshabilitar el botón dinámicamente

```jsx
// Calcula si el form es válido (derivado del estado)
const esValido = nombre.length > 0 && email.includes('@');

<button type="submit" disabled={!esValido}>
  Enviar
</button>
```

Esto es **estado derivado**: no guardas `esValido` en un `useState`, lo calculas directamente del estado existente. Menos estado = menos bugs.

## Limpiar el form tras submit

```jsx
function handleSubmit(e) {
  e.preventDefault();
  // ... procesar ...
  setNombre(''); // Limpiar campo
  setEmail('');  // Limpiar campo
}
```

